    Event.WeatherThunder to listOf(
        Line("आग्गै आंधी-तूफान सै, सुरक्षित जगह देख कै रुक ले, पेड़ां तै दूर।", "Aaggai aandhi-toofaan sai, surakshit jagah dekh ke ruk le, pedaan te door.", "Storm ahead; find a safe place to stop, away from trees."),
