        Line("ध्यान दे, आड़े तै औसत स्पीड गिणी जावैगी, लिमिट मैं, मौज मैं।", "Dhyaan de, aade te ausat speed gini jaavaigi, limit main, mauj main.", "Heads up, average speed is counted from here. In the limit, in good spirits."),
        Line("जोन शुरू सै, लिमिट मैं चाल, कैमरा आड़े भी देखै, ओड़ै भी।", "Zone shuru sai, limit main chaal, camera aade bhi dekhai, odai bhi.", "Zone starts, stay in the limit. Cameras watch here and there too."),
    ),
    Event.AvgZoneEnd to listOf(
        Line("औसत स्पीड जोन खतम, बढ़िया चलाई, पास हो ग्या, फर्स्ट डिवीजन!", "Ausat speed zone khatam, badhiya chalaai, paas ho gya, first division!", "Average-speed zone over, well driven. Passed with first division!"),
        Line("जोन पार, शाबाश! फेर भी लिमिट का ध्यान राखिए।", "Zone paar, shaabaash! Pher bhi limit ka dhyaan raakhiye.", "Zone done, well done! Still mind the limit."),
        Line("मुनीम जी पाच्छै रह गे, पर हम तो आराम तै ए चालांगे।", "Munim ji paachhai rah ge, par ham to aaraam te e chaalaange.", "The accountant's behind us, but we'll keep it easy anyway."),
        Line("औसत स्पीड का इलाका खतम, लठ गाड़ दिए, इब भी मौज तै।", "Ausat speed ka ilaaka khatam, lath gaad diye, ib bhi mauj te.", "Average-speed stretch over. Nailed it, keep it relaxed."),
        Line("जोन खतम! कछुआ जीत ग्या, जिसा हमेशा जीतै सै।", "Zone khatam! Kachhua jeet gya, jisa hamesha jeetai sai.", "Zone over! The tortoise won, like it always does."),
        Line("पार हो ग्या जोन, सड़क खुली सै, पर लिमिट वोए सै।", "Paar ho gya zone, sadak khuli sai, par limit voe sai.", "Through the zone. The road's open, but the limit is the same."),
    ),
    Event.PoliceAhead to listOf(
        Line("आग्गै पुलिस का नाका सै, बेल्ट ला ले अर कागज त्यार राख।", "Aaggai police ka naaka sai, belt la le ar kaagaz tyaar raakh.", "Police check ahead; belt on and keep your papers ready."),
        Line("आग्गै चेकिंग सै, स्पीड कम, पुलिस आळे भाइयां नै राम राम करदे जाइए।", "Aaggai checking sai, speed kam, police aale bhaiyaan nai Ram Ram karde jaaiye.", "Checking ahead, slow down, and greet the police brothers with a Ram Ram."),
        Line("नाका आ रया, धीरे कर, लाइसेंस, आरसी सब गेल्यां सैं ना?", "Naaka aa raya, dheere kar, licence, RC sab gelyaan sain na?", "Checkpoint coming, slow down. Licence and RC on you, right?"),
        Line("आग्गै पुलिस खड़ी सै, आराम तै, सीधे ड्राइवर नै के फिकर!", "Aaggai police khadi sai, aaraam te, seedhe driver nai ke fikar!", "Police ahead, easy. An honest driver has nothing to worry about!"),
        Line("चेकिंग चाल री सै, कहवैं तो रुक ज्याइए, शीशा नीचे अर स्माइल ऊपर।", "Checking chaal ri sai, kahvain to ruk jyaaiye, sheesha neeche ar smile oopar.", "Checking on; stop if they signal. Window down, smile up."),
        Line("आग्गै नाका सै, लिमिट मैं अर बेल्ट मैं, पुलिस भी राजी, घरआळे भी।", "Aaggai naaka sai, limit main ar belt main, police bhi raazi, gharaale bhi.", "Checkpoint ahead; in the limit and belted up. Police happy, family happy."),
    ),
    Event.JamAhead to listOf(
        Line("आग्गै जाम सै, आराम तै, हॉर्न तै जाम ना खुलदा, सबर तै खुलै सै।", "Aaggai jaam sai, aaraam te, horn te jaam na khulda, sabar te khulai sai.", "Jam ahead, easy. Horns don't clear a jam, patience does."),
        Line("आग्गै गाड्डी अटकी पड़ी सैं, धीरे हो ले, गाणा बदल द्यूं के?", "Aaggai gaadi atki padi sain, dheere ho le, gaana badal dyun ke?", "Cars are stuck ahead, slow down. Shall I change the song?"),
        Line("जाम आ रया, टैम लागैगा, चाल, मैं चुटकला सुणाऊं?", "Jaam aa raya, time laagaiga, chaal, main chutkala sunaaun?", "Jam coming, it'll take time. Shall I tell you a joke?"),
        Line("आग्गै ट्रैफिक घणा सै, बार-बार लेन ना बदलिए, सबनै घरां जाणा सै।", "Aaggai traffic ghana sai, baar-baar lane na badaliye, sabnai gharaan jaana sai.", "Heavy traffic ahead, don't keep switching lanes. Everyone's going home."),
        Line("जाम सै आग्गै, ठंडा दिमाग राख, गुस्सा अर क्लच दोनूं हळवे।", "Jaam sai aaggai, thanda dimaag raakh, gussa ar clutch donun halve.", "Jam ahead; keep a cool head. Go easy on the temper and the clutch."),
        Line("आग्गै जाम, धीरे हो ले, आज सड़क बारात की चाल चाल री सै।", "Aaggai jaam, dheere ho le, aaj sadak baaraat ki chaal chaal ri sai.", "Jam ahead, slow down. The road's moving at wedding-procession pace."),
    ),
    Event.MobileCameraAhead to listOf(
        Line("आग्गै स्पीड गन सै, लिमिट मैं चाल, पुलिस आळे भाइयां नै राम राम।", "Aaggai speed gun sai, limit main chaal, police aale bhaiyaan nai Ram Ram.", "Speed gun ahead, stay in the limit. Ram Ram to the police brothers."),
        Line("आग्गै मोबाइल कैमरा सै, मंदी कर ले, छुप कै खड़्या सै, पर मन्नै बेरा सै!", "Aaggai mobile camera sai, mandi kar le, chhup ke khadya sai, par mannai bera sai!", "Mobile camera ahead, slow down. It's hiding, but I know!"),
        Line("आग्गै इंटरसेप्टर सै, लिमिट मैं, आज शरीफ ड्राइवर बण कै दिखा।", "Aaggai interceptor sai, limit main, aaj shareef driver ban ke dikha.", "Interceptor ahead, stay in the limit. Show them a model driver today."),
        Line("आग्गै स्पीड नापण आळे सैं, धीरे कर, म्हारी तो रोज की आराम आळी चाल सै।", "Aaggai speed naapan aale sain, dheere kar, mhaari to roj ki aaraam aali chaal sai.", "Speed checkers ahead, slow down. Easy pace is our daily style anyway."),
        Line("मोबाइल कैमरा की खबर सै, स्पीड कम, फोटो तो ब्याह मैं खिंचवावांगे।", "Mobile camera ki khabar sai, speed kam, photo to byaah main khinchwaawange.", "Mobile camera reported, slow down. We'll pose for photos at a wedding."),
        Line("आग्गै स्पीड गन सै, लिमिट मैं राख, बढ़िया, तू तो पहलां ए आराम तै सै।", "Aaggai speed gun sai, limit main raakh, badhiya, tu to pahlaan e aaraam te sai.", "Speed gun ahead, keep in the limit. Good, you're already easy on it."),
    ),
    Event.FastagLowBalance to listOf(
        Line("%1\$s रुपये ए बचे सैं फास्टैग मैं, रुक कै रिचार्ज कर लिए।", "%1\$s rupaye e bache sain FASTag main, ruk ke recharge kar liye.", "Only ₹{balance} left on FASTag; recharge once you've stopped."),
        Line("%1\$s रुपये मैं अगला टोल भी मुश्किल, घरां पहुँच कै रिचार्ज कर दिए।", "%1\$s rupaye main agla toll bhi mushkil, gharaan pahunch ke recharge kar diye.", "₹{balance} may not cover the next toll; recharge when you get home."),
        Line("फास्टैग की टंकी खाली होण लाग री, बचे बस %1\$s", "FASTag ki tanki khaali hon laag ri, bache bas %1\$s", "The FASTag 'tank' is running dry, just {balance} left."),
        Line("फास्टैग भूखा सै, रुक कै रिचार्ज का चूरमा खुवा दिए।", "FASTag bhookha sai, ruk ke recharge ka choorma khuwa diye.", "FASTag is hungry; once you stop, feed it a recharge 'choorma'."),
        Line("बैलेंस कम सै, ना तो टोल पै अटकांगे, गाड्डी रोक कै रिचार्ज करिए।", "Balance kam sai, na to toll pe atkaange, gaadi rok ke recharge kariye.", "Balance is low or we'll get stuck at a toll; stop the car, then recharge."),
        Line("फास्टैग मैं पीस्से थोड़े सैं, अगले ढाबे पै रुक कै रिचार्ज कर लियो।", "FASTag main peesse thode sain, agle dhaabe pe ruk ke recharge kar liyo.", "Not much money on FASTag; recharge when we stop at the next dhaba."),
    ),
