    Event.NightDrive to listOf(
        Line("रात हो गी, हळवे चलाइए, नींद आवै तो रुक ल्यांगे, कोए बात ना।", "Raat ho gi, halve chalaaiye, neend aavai to ruk lyaange, koi baat na.", "It's night, drive gently. If you get sleepy we'll stop, no problem."),
        Line("रात का सफर सै, हेडलाइट ठीक, स्पीड कम, मैं जाग्गूं सूं थारे गेल्यां।", "Raat ka safar sai, headlight theek, speed kam, main jaaggun sun thaare gelyaan.", "Night trip: headlights right, speed down. I'm awake with you."),
        Line("आंख भारी लागैं तो बता दिए, ढाबे पै चाय पी ल्यांगे।", "Aankh bhaari laagain to bata diye, dhaabe pe chai pi lyaange.", "If your eyes feel heavy, tell me; we'll have tea at a dhaba."),
        Line("सामणै की लाइट चुंधियावै तो उल्टे हाथ की सफेद पट्टी पै नजर राख।", "Saamnai ki light chundhiyaavai to ulte haath ki safed patti pe nazar raakh.", "If oncoming lights dazzle you, keep your eyes on the left white line."),
        Line("रात शांत सै, गाणे हळवे कर द्यूं सूं, तू बस सड़क देख।", "Raat shaant sai, gaane halve kar dyun sun, tu bas sadak dekh.", "The night is quiet; I'll turn the music down, you just watch the road."),
        Line("घणी रात हो गी जी, घरां आळे जाग रे होंगे, आराम तै पहुँचांगे।", "Ghani raat ho gi ji, gharaan aale jaag re honge, aaraam te pahunchaange.", "It's late; the family must be up waiting. We'll get there safely."),
